head -3 data/stale-liveness.tsv
echo "---"
node -e "
const fs=require('fs');
const liveness = fs.readFileSync('data/stale-liveness.tsv','utf8').split('\n').filter(Boolean);
const header = liveness[0].split('\t');
console.log('HEADER:', header.join('|'));
const map = {};
for (const l of liveness.slice(1)) {
  const cols = l.split('\t');
  map[cols[0]] = cols;
}
const lines = fs.readFileSync('triage-batch/s2.txt','utf8').split('\n').filter(Boolean);
for (const l of lines) {
  const url = l.split('|').pop().trim();
  const row = map[url];
  console.log(url, row ? (row[1]+' | '+row[2]) : 'NOTFOUND');
}
"

